+/**
+ * Theoretical use (from imported sales, by recipe) against actual use (every
+ * consume movement) per item between two days, inclusive. Items with neither
+ * above zero are left out; `diffQty` is actual minus theoretical.
+ */
+export function varianceReport(store, from, to) {
+  const theoretical = new Map();
+  const actual = new Map();
+  for (const sale of store.data.sales ?? []) {
+    const day = sale.soldAt.slice(0, 10);
+    if (day < from || day > to) continue;
+    for (const line of sale.lines) {
+      const dish = store.data.dishes.find((d) => d.id === line.dishId);
+      const recipe = dish && store.data.recipes.find((r) => r.id === dish.recipeId);
+      if (!recipe) continue;
+      for (const n of scaled(recipe, line.qty)) theoretical.set(n.itemId, (theoretical.get(n.itemId) ?? 0) + n.qty);
+    }
+  }
+  for (const m of store.data.movements) {
+    if (m.type !== "consume") continue;
+    const day = m.at.slice(0, 10);
+    if (day < from || day > to) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) actual.set(batch.itemId, (actual.get(batch.itemId) ?? 0) + m.qty);
+  }
+  return listItems(store)
+    .map((item) => {
+      const theoreticalQty = round3(theoretical.get(item.id) ?? 0);
+      const actualQty = round3(actual.get(item.id) ?? 0);
+      return { itemId: item.id, name: item.name, unit: item.unit, theoreticalQty, actualQty, diffQty: round3(actualQty - theoreticalQty) };
+    })
+    .filter((l) => l.theoreticalQty > 0 || l.actualQty > 0);
+}
